use pele::compat::{
    diagrams::swimlane::{Swimlane, SwimlaneModel},
    public::*,
    text::MetricsResources,
    *,
};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};
fn reference(a: &Atom) -> u32 {
    if let Atom::Ref(i) = a {
        *i
    } else {
        panic!("reference")
    }
}
fn root(g: &ModelGraph) -> u32 {
    reference(&g.root)
}
fn field<'a>(g: &'a ModelGraph, id: u32, key: &str) -> &'a Atom {
    &g.nodes[id as usize]
        .properties()
        .iter()
        .find(|p| g.strings[p.key as usize].is(key))
        .unwrap()
        .value
}
fn set(g: &mut ModelGraph, id: u32, key: &str, v: Atom) {
    if let Some(i) = g.nodes[id as usize]
        .properties()
        .iter()
        .position(|p| g.strings[p.key as usize].is(key))
    {
        g.nodes[id as usize].properties_mut()[i].value = v;
        return;
    }
    let key_id = g.strings.len() as u32;
    g.strings.push(key.into());
    g.nodes[id as usize].properties_mut().push(Property {
        key: key_id,
        value: v,
        flags: 7,
    });
}
fn string(g: &mut ModelGraph, s: &str) -> Atom {
    let i = g.strings.len() as u32;
    g.strings.push(s.into());
    Atom::String(i)
}
fn object(g: &mut ModelGraph) -> u32 {
    let i = g.nodes.len() as u32;
    g.nodes.push(Node::Object { properties: vec![] });
    i
}
fn array(g: &mut ModelGraph, values: Vec<Atom>) -> u32 {
    let i = g.nodes.len() as u32;
    g.nodes.push(Node::Array {
        length: values.len() as u32,
        properties: vec![],
    });
    for (n, a) in values.into_iter().enumerate() {
        set(g, i, &n.to_string(), a)
    }
    i
}
fn keys(g: &ModelGraph, id: u32) -> Vec<String> {
    g.nodes[id as usize]
        .properties()
        .iter()
        .map(|p| g.strings[p.key as usize].well_formed().unwrap())
        .collect()
}
fn fingerprint(g: &ModelGraph) -> String {
    serde_json::to_string(g).unwrap()
}
fn hash(s: &str) -> String {
    format!("{:x}", Sha256::digest(s.as_bytes()))
}
fn call(
    doc: &mut PublicDocument,
    name: &str,
    args: impl FnOnce(&mut ModelGraph) -> Vec<Atom>,
) -> InvocationOutcome {
    let method = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == name)
        .unwrap()
        .id;
    let mut g = doc.snapshot().unwrap();
    let receiver = g.root.clone();
    let arguments = args(&mut g);
    doc.apply(doc.revision(), g).unwrap();
    doc.invoke(
        doc.revision(),
        MethodCall {
            method,
            receiver,
            arguments,
        },
        &mut MetricsResources,
    )
    .unwrap()
}
fn success(o: InvocationOutcome) -> ModelGraph {
    assert!(matches!(o.result, Ok(Atom::Undefined)));
    o.graph
}
struct Counted {
    parses: Arc<AtomicUsize>,
    renders: Arc<AtomicUsize>,
}
impl DiagramModule for Counted {
    type Model = SwimlaneModel;
    fn descriptor(&self) -> ModuleDescriptor {
        Swimlane.descriptor()
    }
    fn parse(&self, c: ParseContext<'_>) -> Result<Self::Model, PeleError> {
        self.parses.fetch_add(1, Ordering::SeqCst);
        Swimlane.parse(c)
    }
    fn render(
        &self,
        m: &Self::Model,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        Swimlane.render(m, c, o, h)
    }
}
impl PublicDiagramModule for Counted {
    type PublicState = <Swimlane as PublicDiagramModule>::PublicState;
    fn model_schema(&self) -> &'static ModelSchema {
        Swimlane.model_schema()
    }
    fn create_public(&self, m: &Self::Model) -> Result<Self::PublicState, PeleError> {
        Swimlane.create_public(m)
    }
    fn export_public(&self, s: &Self::PublicState) -> Result<ModelGraph, PeleError> {
        Swimlane.export_public(s)
    }
    fn apply_public(&self, s: &mut Self::PublicState, g: ModelGraph) -> Result<(), PeleError> {
        Swimlane.apply_public(s, g)
    }
    fn invoke_public(
        &self,
        s: &mut Self::PublicState,
        call: MethodCall,
        c: &Object,
        h: &mut dyn RenderResources,
    ) -> Result<Atom, PublicError> {
        Swimlane.invoke_public(s, call, c, h)
    }
    fn render_public(
        &self,
        s: &mut Self::PublicState,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        self.renders.fetch_add(1, Ordering::SeqCst);
        Swimlane.render_public(s, c, o, h)
    }
}
struct Host<'a>(&'a Json);
impl RenderResources for Host<'_> {
    fn text_width(&mut self, r: TextRequest<'_>) -> Result<f64, PeleError> {
        if self.0["measure"] == "fixed" {
            Ok(r.text.encode_utf16().count() as f64
                * r.size
                * if r.style & 1 != 0 { 0.71 } else { 0.6 })
        } else {
            MetricsResources.text_width(r)
        }
    }
    fn icon(&mut self, name: &str) -> Result<Option<TrustedSvg>, PeleError> {
        Ok(self.0["icons"][name]
            .as_str()
            .map(|s| TrustedSvg::from_trusted_markup(s.into())))
    }
}
#[test]
fn historical_swimlane_corpus_matches_through_mutable_public_documents() {
    let fixture: Json = {
        use std::io::Read;
        let mut decoder = flate2::read::GzDecoder::new(
            include_bytes!("../../../fixtures/pele/swimlane.json.gz").as_slice(),
        );
        let mut bytes = Vec::new();
        decoder.read_to_end(&mut bytes).unwrap();
        serde_json::from_slice(&bytes).unwrap()
    };
    let mut engine = PublicEngine::empty();
    engine.register(Swimlane);
    let mut failures = vec![];
    for case in fixture["cases"].as_array().unwrap() {
        let options: RenderOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let actual = engine
            .parse(case["source"].as_str().unwrap(), &options.parse)
            .and_then(|mut d| d.render(&options, &mut Host(&case["host"])));
        let actual = match actual {
            Ok(r) => {
                let mut result = serde_json::to_value(r).unwrap();
                if case["expected"]["result"].get("svgSha256").is_some() {
                    let svg = result.as_object_mut().unwrap().remove("svg").unwrap();
                    result["svgSha256"] = hash(svg.as_str().unwrap()).into();
                }
                serde_json::json!({"result":result})
            }
            Err(e) => serde_json::json!({"error":e}),
        };
        let expected = if case["expected"].get("error").is_some() {
            serde_json::json!({"error":case["expected"]["error"]})
        } else {
            serde_json::json!({"result":case["expected"]["result"]})
        };
        if actual != expected {
            failures.push((case["id"].clone(), actual, expected));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mutable corpus mismatches: {:?}",
        failures.len(),
        failures.iter().take(5).collect::<Vec<_>>()
    );
}
fn canonical(g: &ModelGraph) -> Json {
    use std::collections::{HashMap, VecDeque};
    fn atom(
        g: &ModelGraph,
        a: &Atom,
        ids: &mut HashMap<u32, usize>,
        queue: &mut VecDeque<u32>,
    ) -> Json {
        match a {
            Atom::Undefined => serde_json::json!(["undefined"]),
            Atom::Null => serde_json::json!(["null"]),
            Atom::Bool(v) => serde_json::json!(["bool", v]),
            Atom::Number(v) => serde_json::json!(["number", format!("{:016x}", v.to_bits())]),
            Atom::String(i) => serde_json::json!(["string", g.strings[*i as usize].0]),
            Atom::Ref(id) => {
                let next = ids.len();
                let index = *ids.entry(*id).or_insert_with(|| {
                    queue.push_back(*id);
                    next
                });
                serde_json::json!(["ref", index])
            }
            Atom::BuiltinFunction(id) => serde_json::json!(["builtin", id]),
            Atom::HostReference(id) => serde_json::json!(["host", id]),
        }
    }
    let mut ids = HashMap::new();
    let mut queue = VecDeque::new();
    let root = atom(g, &g.root, &mut ids, &mut queue);
    let mut nodes = Vec::new();
    while let Some(id) = queue.pop_front() {
        let n = &g.nodes[id as usize];
        let mut out = serde_json::json!({"kind":match n{Node::Instance{..}=>"instance",Node::Object{..}=>"object",Node::Array{..}=>"array",Node::Map{..}=>"map",Node::Set{..}=>"set",Node::Date{..}=>"date"}});
        match n {
            Node::Instance { prototype, .. } => out["prototype"] = prototype.0.into(),
            Node::Array { length, .. } => out["length"] = (*length).into(),
            Node::Map { entries, .. } => {
                out["entries"] = entries
                    .iter()
                    .map(|(k, v)| {
                        serde_json::json!([
                            atom(g, k, &mut ids, &mut queue),
                            atom(g, v, &mut ids, &mut queue)
                        ])
                    })
                    .collect()
            }
            Node::Set { values, .. } => {
                out["values"] = values
                    .iter()
                    .map(|v| atom(g, v, &mut ids, &mut queue))
                    .collect()
            }
            _ => {}
        }
        let mut properties = n.properties().iter().collect::<Vec<_>>();
        let index = |p: &&Property| {
            g.strings[p.key as usize].well_formed().and_then(|s| {
                s.parse::<u32>()
                    .ok()
                    .filter(|n| *n != u32::MAX && n.to_string() == s)
            })
        };
        properties.sort_by(|a, b| match (index(a), index(b)) {
            (Some(x), Some(y)) => x.cmp(&y),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            _ => std::cmp::Ordering::Equal,
        });
        out["properties"] = properties
            .into_iter()
            .map(|p| {
                serde_json::json!([
                    g.strings[p.key as usize].0,
                    atom(g, &p.value, &mut ids, &mut queue),
                    p.flags
                ])
            })
            .collect();
        nodes.push(out);
    }
    serde_json::json!({"root":root,"nodes":nodes})
}
fn selector(g: &ModelGraph, path: &[Json]) -> Atom {
    let mut value = g.root.clone();
    for key in path {
        let id = reference(&value);
        value = if let Some(k) = key.get("map") {
            let Node::Map { entries, .. } = &g.nodes[id as usize] else {
                panic!("map")
            };
            entries.iter().find(|(k0,_)|matches!(k0,Atom::String(i)if g.strings[*i as usize].is(k.as_str().unwrap()))).unwrap().1.clone()
        } else {
            let key = key
                .as_str()
                .map(str::to_string)
                .unwrap_or_else(|| key.as_u64().unwrap().to_string());
            g.nodes[id as usize]
                .properties()
                .iter()
                .find(|p| g.strings[p.key as usize].is(&key))
                .map_or(Atom::Undefined, |p| p.value.clone())
        };
    }
    value
}
fn value(g: &mut ModelGraph, v: &Json) -> Atom {
    match v {
        Json::Null => Atom::Null,
        Json::Bool(v) => Atom::Bool(*v),
        Json::Number(v) => Atom::Number(v.as_f64().unwrap()),
        Json::String(s) => string(g, s),
        Json::Array(values) => {
            let values = values.iter().map(|v| value(g, v)).collect();
            Atom::Ref(array(g, values))
        }
        Json::Object(o) => {
            if let Some(path) = o.get("ref") {
                return selector(g, path.as_array().unwrap());
            }
            if o.contains_key("undefined") {
                return Atom::Undefined;
            }
            if let Some(units) = o.get("utf16") {
                let id = g.strings.len() as u32;
                g.strings.push(JsString(
                    units
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|n| n.as_u64().unwrap() as u16)
                        .collect(),
                ));
                return Atom::String(id);
            }
            if let Some(n) = o.get("number") {
                return Atom::Number(match n.as_str().unwrap() {
                    "nan" => f64::NAN,
                    "inf" => f64::INFINITY,
                    "-inf" => f64::NEG_INFINITY,
                    "-0" => -0.,
                    _ => panic!("number"),
                });
            }
            let id = object(g);
            for (k, v) in o {
                let value = value(g, v);
                set(g, id, k, value)
            }
            Atom::Ref(id)
        }
    }
}
fn public_error(e: &PublicError) -> Json {
    match e {
        PublicError::Pele(e) => {
            serde_json::json!({"name":e.name,"message":e.message,"code":e.code,"type":e.diagram_type})
        }
        PublicError::JavaScript { name, .. } => {
            serde_json::json!({"name":match name{JavaScriptErrorKind::TypeError=>"TypeError",JavaScriptErrorKind::RangeError=>"RangeError",_=>"Error"}})
        }
        _ => panic!("host error"),
    }
}
#[test]
fn pinned_swimlane_mutable_graph_methods_and_complete_svg_vectors() {
    let cases: Json = serde_json::from_str(FLOW_VECTORS).unwrap();
    let mut engine = PublicEngine::empty();
    engine.register(Swimlane);
    for c in cases.as_array().unwrap() {
        let options: RenderOptions = serde_json::from_value(c["options"].clone()).unwrap();
        let mut doc = engine
            .parse(c["source"].as_str().unwrap(), &options.parse)
            .unwrap();
        assert_eq!(
            canonical(&doc.snapshot().unwrap()),
            c["initial"],
            "initial {}",
            c["id"]
        );
        for step in c["steps"].as_array().unwrap() {
            let op = &step["op"];
            let actual = if let Some(name) = op["method"].as_str() {
                let method = doc
                    .model_schema()
                    .methods
                    .iter()
                    .find(|m| m.name == name)
                    .unwrap()
                    .id;
                let mut g = doc.snapshot().unwrap();
                let receiver = g.root.clone();
                let args = op["args"].as_array().unwrap();
                let arguments = args.iter().map(|v| value(&mut g, v)).collect();
                doc.apply(doc.revision(), g).unwrap();
                let out = doc
                    .invoke(
                        doc.revision(),
                        MethodCall {
                            method,
                            receiver,
                            arguments,
                        },
                        &mut MetricsResources,
                    )
                    .unwrap();
                match out.result {
                    Ok(result) => {
                        let mut g = out.graph;
                        g.root = result;
                        serde_json::json!({"result":canonical(&g)})
                    }
                    Err(e) => serde_json::json!({"error":public_error(&e)}),
                }
            } else {
                let mut g = doc.snapshot().unwrap();
                if let Some(path) = op["set"].as_array() {
                    let target = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path
                        .last()
                        .unwrap()
                        .as_str()
                        .map(str::to_string)
                        .unwrap_or_else(|| path.last().unwrap().as_u64().unwrap().to_string());
                    let v = value(&mut g, &op["value"]);
                    set(&mut g, target, &key, v)
                } else if let Some(path) = op["reverse"].as_array() {
                    let id = reference(&selector(&g, path));
                    let Node::Array { length, .. } = g.nodes[id as usize] else {
                        panic!("array")
                    };
                    let values = (0..length)
                        .map(|i| field(&g, id, &i.to_string()).clone())
                        .rev()
                        .collect::<Vec<_>>();
                    for (i, v) in values.into_iter().enumerate() {
                        set(&mut g, id, &i.to_string(), v)
                    }
                } else if let Some(path) = op["mapDelete"].as_array() {
                    let id = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path.last().unwrap().as_str().unwrap();
                    let Node::Map { entries, .. } = &mut g.nodes[id as usize] else {
                        panic!("map")
                    };
                    entries.retain(
                        |(k, _)| !matches!(k,Atom::String(i)if g.strings[*i as usize].is(key)),
                    )
                } else if let Some(path) = op["mapSet"].as_array() {
                    let id = reference(&selector(&g, path));
                    let key = value(&mut g, &op["key"]);
                    let v = value(&mut g, &op["value"]);
                    let Node::Map { entries, .. } = &mut g.nodes[id as usize] else {
                        panic!("map")
                    };
                    entries.push((key, v));
                } else if let Some(path) = op["readonly"].as_array() {
                    let id = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path.last().unwrap().as_str().unwrap();
                    if let Some(i) = g.nodes[id as usize]
                        .properties()
                        .iter()
                        .position(|p| g.strings[p.key as usize].is(key))
                    {
                        g.nodes[id as usize].properties_mut()[i].flags &= !2;
                    } else {
                        set(&mut g, id, key, Atom::Undefined);
                        g.nodes[id as usize]
                            .properties_mut()
                            .last_mut()
                            .unwrap()
                            .flags = 0
                    }
                } else {
                    panic!("operation")
                };
                doc.apply(doc.revision(), g).unwrap();
                serde_json::json!({"result":{"root":["undefined"],"nodes":[]}})
            };
            let expected = if step.get("error").is_some() {
                serde_json::json!({"error":step["error"]})
            } else {
                serde_json::json!({"result":step["result"]})
            };
            assert_eq!(actual, expected, "result {} {:?}", c["id"], op);
            assert_eq!(
                canonical(&doc.snapshot().unwrap()),
                step["graph"],
                "graph {} {:?}",
                c["id"],
                op
            );
        }
        for expected in c["outputs"].as_array().unwrap() {
            let mut o = RenderOptions::default();
            o.render.max_width = expected["maxWidth"].as_f64();
            let before = fingerprint(&doc.snapshot().unwrap());
            let actual = doc.render(&o, &mut MetricsResources);
            if expected.get("error").is_some() {
                let e = actual.unwrap_err();
                assert_eq!(
                    serde_json::json!({"name":e.name,"message":e.message,"code":e.code,"type":e.diagram_type}),
                    expected["error"],
                    "render {}",
                    c["id"]
                );
            } else {
                let r = actual.unwrap().rendered;
                assert_eq!(
                    hash(&r.svg),
                    expected["svgSha256"].as_str().unwrap(),
                    "svg {} max {:?}",
                    c["id"],
                    o.render.max_width
                );
                assert_eq!(
                    (r.width, r.height),
                    (
                        expected["width"].as_f64().unwrap(),
                        expected["height"].as_f64().unwrap()
                    )
                );
                assert_eq!(serde_json::to_value(&r.links).unwrap(), expected["links"]);
            }
            assert_eq!(fingerprint(&doc.snapshot().unwrap()), before);
        }
    }
}

struct FailingHost;
impl RenderResources for FailingHost {
    fn text_width(&mut self, _: TextRequest<'_>) -> Result<f64, PeleError> {
        Err(PeleError::new("host width failed", ErrorCode::Semantic))
    }
}
#[test]
fn swimlane_public_ownership_source_equivalent_builders_native_pixels_and_recovery() {
    let source="swimlane-beta LR\naccTitle: Native title\nA[Before] --> B\nclassDef blue fill:#247acd,color:#ffffff,stroke:#164779\nclass A blue\nclick A \"https://example.com\" \"Tip\" _blank";
    let parses = Arc::new(AtomicUsize::new(0));
    let renders = Arc::new(AtomicUsize::new(0));
    let mut engine = PublicEngine::empty();
    engine.register(Counted {
        parses: parses.clone(),
        renders: renders.clone(),
    });
    let mut doc = engine.parse(source, &Default::default()).unwrap();
    assert_eq!(doc.model_schema().id, "pele/flowchart@1");
    assert_eq!(doc.model_schema().methods.len(), 19);
    assert!(doc.model_schema().prototypes[0]
        .members
        .iter()
        .all(|m| m.flags == 6));
    let initial = doc.snapshot().unwrap();
    assert_eq!(
        keys(&initial, root(&initial)),
        [
            "type",
            "direction",
            "nodes",
            "edges",
            "subgraphs",
            "classes",
            "tooltips",
            "defaultEdgeStyle",
            "defaultInterpolate",
            "title",
            "accTitle",
            "accDescr",
            "subgraphLookup",
            "members",
            "edgeById",
            "pairCount",
            "subCount",
            "options"
        ]
    );
    assert!(initial.nodes[reference(&initial.root) as usize]
        .properties()
        .iter()
        .all(|p| p.flags == 7));
    success(call(&mut doc, "addVertex", |g| {
        let id = string(g, "A");
        let object = value(g, &serde_json::json!({"text":" After ","type":"text"}));
        vec![id, object]
    }));
    let mut immutable = Engine::empty();
    immutable.register(Swimlane);
    let expected = immutable
        .render_source(
            &source.replace("Before", "After"),
            &Default::default(),
            &mut MetricsResources,
        )
        .unwrap();
    let actual = doc
        .render(&Default::default(), &mut MetricsResources)
        .unwrap();
    assert_eq!(
        serde_json::to_value(&actual).unwrap(),
        serde_json::to_value(&expected).unwrap()
    );
    let mut graph = doc.snapshot().unwrap();
    let root = root(&graph);
    set(&mut graph, root, "type", Atom::Bool(false));
    doc.apply(doc.revision(), graph).unwrap();
    engine.register(Swimlane);
    drop(engine);
    assert_eq!(doc.diagram_type().as_str(), "swimlane");
    let mut native = RenderOptions::default();
    native.render.native_theme = Some(NativeTheme::default());
    native.parse.preparation.limit = 0;
    native.parse.max_edges = 0;
    let native_result = doc.render(&native, &mut MetricsResources).unwrap();
    assert_eq!(native_result.diagram_type.as_str(), "swimlane");
    let rendered = native_result.rendered;
    assert!(rendered.svg.contains("pele-lane"));
    assert_eq!(rendered.links.len(), 1);
    assert_eq!(rendered.links[0].id, "A");
    assert!(!rendered.svg.contains("color-mix("));
    let xml = roxmltree::Document::parse(&rendered.svg).unwrap();
    assert!(xml
        .descendants()
        .any(|n| n.has_tag_name("title") && n.text() == Some("Native title")));
    let tree = resvg::usvg::Tree::from_str(&rendered.svg, &Default::default()).unwrap();
    let mut pixels =
        resvg::tiny_skia::Pixmap::new(rendered.width as u32, rendered.height as u32).unwrap();
    resvg::render(
        &tree,
        resvg::tiny_skia::Transform::identity(),
        &mut pixels.as_mut(),
    );
    assert!(
        pixels
            .pixels()
            .iter()
            .filter(|p| p.alpha() > 200 && p.blue() > 150 && p.red() < 80)
            .count()
            > 500
    );
    native.render.max_width = Some(150.);
    let narrow = doc.render(&native, &mut MetricsResources).unwrap().rendered;
    assert!(narrow.width < rendered.width);
    let before = fingerprint(&doc.snapshot().unwrap());
    assert!(doc
        .render(&Default::default(), &mut FailingHost)
        .unwrap_err()
        .message
        .contains("host width failed"));
    let mut limit = RenderOptions::default();
    limit.render.output_limit = Some(20);
    assert_eq!(
        doc.render(&limit, &mut MetricsResources).unwrap_err().code,
        ErrorCode::Limit
    );
    assert_eq!(fingerprint(&doc.snapshot().unwrap()), before);
    assert_eq!(
        doc.render(&Default::default(), &mut MetricsResources)
            .unwrap()
            .rendered
            .svg,
        actual.rendered.svg
    );
    assert_eq!(parses.load(Ordering::SeqCst), 1);
    assert!(renders.load(Ordering::SeqCst) >= 6);
}

#[test]
fn swimlane_and_flowchart_share_actual_model_schema_and_native_method_identity() {
    use pele::compat::diagrams::flowchart::Flowchart;
    assert!(std::ptr::eq(
        Swimlane.model_schema(),
        Flowchart.model_schema()
    ));
    assert!(std::ptr::eq(
        &Swimlane.model_schema().prototypes[0],
        &Flowchart.model_schema().prototypes[0]
    ));
    assert!(std::ptr::eq(
        Swimlane.model_schema().methods.as_ptr(),
        Flowchart.model_schema().methods.as_ptr()
    ));
    let source="flowchart LR\nsubgraph first[First lane]\nA --> B\nend\nsubgraph second[Second lane]\nC --> D\nend\nB --> C";
    let mut engine = PublicEngine::empty();
    engine.register(Flowchart);
    engine.register(Swimlane);
    let mut flow = engine.parse(source, &Default::default()).unwrap();
    let mut lane = engine
        .parse(
            &source.replacen("flowchart", "swimlane-beta", 1),
            &Default::default(),
        )
        .unwrap();
    let graph = lane.snapshot().unwrap();
    assert!(graph
        .text(field(&graph, root(&graph), "type"))
        .unwrap()
        .is("flowchart"));
    assert_eq!(canonical(&graph), canonical(&flow.snapshot().unwrap()));
    assert_eq!(flow.diagram_type().as_str(), "flowchart");
    assert_eq!(lane.diagram_type().as_str(), "swimlane");
    let old_lane = lane
        .render(&Default::default(), &mut MetricsResources)
        .unwrap();
    let old_flow = flow
        .render(&Default::default(), &mut MetricsResources)
        .unwrap();
    assert_eq!(old_lane.diagram_type.as_str(), "swimlane");
    assert!(old_lane.rendered.svg.contains("pele-lane"));
    assert!(!old_flow.rendered.svg.contains("pele-lane"));
    assert_ne!(old_lane.rendered.svg, old_flow.rendered.svg);
    for doc in [&mut flow, &mut lane] {
        success(call(doc, "setDirection", |g| vec![string(g, "TB")]));
    }
    assert_eq!(
        canonical(&lane.snapshot().unwrap()),
        canonical(&flow.snapshot().unwrap())
    );
    assert_ne!(
        lane.render(&Default::default(), &mut MetricsResources)
            .unwrap()
            .rendered
            .svg,
        flow.render(&Default::default(), &mut MetricsResources)
            .unwrap()
            .rendered
            .svg
    );
}
